import{Port}from'../../core/index.js';import{THREE,materials,box,solid,polygon,circleHole,ring,cylinder,roundedRect,FACE,portQuaternion}from'./geometry.js';import{spec}from'./dimensions.js';import{addStickers}from'./stickers.js';
const tin=()=>materials.metal(0xbfc0b2,{roughness:.48}),black=()=>materials.plastic(0x20241f,{roughness:.78});
function frontOutline(){const s=new THREE.Shape();s.moveTo(-8.5,-12);s.lineTo(-5,-12);s.lineTo(-5,-5.8);s.lineTo(5,-5.8);s.lineTo(5,-12);s.lineTo(8.5,-12);s.absarc(8.5,-8.5,3.5,-Math.PI/2,0,false);s.lineTo(12,8.5);s.absarc(8.5,8.5,3.5,0,Math.PI/2,false);s.lineTo(-8.5,12);s.absarc(-8.5,8.5,3.5,Math.PI/2,Math.PI,false);s.lineTo(-12,-8.5);s.absarc(-8.5,-8.5,3.5,Math.PI,Math.PI*1.5,false);s.closePath();return s;}
function side(sign){const s=new THREE.Shape();s.moveTo(0,12);s.lineTo(-8.5,12);s.absarc(-8.5,8.5,3.5,Math.PI/2,Math.PI,false);s.lineTo(-12,-8.5);s.absarc(-8.5,-8.5,3.5,Math.PI,Math.PI*1.5,false);s.lineTo(-5,-12);s.lineTo(-5,-11);s.lineTo(-8.5,-11);s.absarc(-8.5,-8.5,2.5,Math.PI*1.5,Math.PI,true);s.lineTo(-11,8.5);s.absarc(-8.5,8.5,2.5,Math.PI,Math.PI/2,true);s.lineTo(0,11);s.closePath();return sign<0?s:polygon(s.getPoints(48).map(v=>[-v.x,v.y]).reverse());}
function shell(host){const white=materials.plastic(0xe8e7df,{roughness:.74}),front=(r)=>{const s=frontOutline();for(const x of[-8,8])circleHole(s,x,0,r);circleHole(s,0,0,2.6);for(const[x,y]of spec.inferred.ventCentres)s.holes.push(roundedRect(.65,2.6,.3,{cx:x,cy:y,path:new THREE.Path()}));return s;},lid=solid(host.body,front(2.5),.7,[0,0,5.3],white,'U090 own reconstructed front lower plate and real vent bore walls'),face=solid(host.body,front(3.1),.5,[0,0,6],white,'U090 own front face and real mounting counterbores'),labelSeat=cylinder(host.body,2.6,1.16,[0,0,5.88],white,'U090 actual round front-label recess floor,not a hole-covering image'),backShape=()=>{const s=roundedRect(24,24,3.5);for(const x of[-8,8])circleHole(s,x,0,2.5);circleHole(s,0,0,1.65);return s;},back=solid(host.body,backShape(),.88,[0,0,-6.38],white,'U090 own reconstructed rear pan with true mounting and fixing bores'),rimShape=backShape();rimShape.holes.push(roundedRect(16.5,4.6,.15,{cy:7.25,path:new THREE.Path()}));
 const m=polygon([[-4.6,-10],[-4.6,-4.8],[-3.9,-4.8],[-2.35,-6.85],[-.8,-4.8],[-.1,-4.8],[-.1,-10],[-.8,-10],[-.8,-6.05],[-2.35,-8.1],[-3.9,-6.05],[-3.9,-10]]),five=polygon([[.35,-4.69],[4.55,-4.69],[4.55,-5.39],[1.05,-5.39],[1.05,-6.59],[3.25,-6.59],[4.2,-7.09],[4.65,-8.09],[4.4,-9.19],[3.5,-9.89],[.35,-9.89],[.35,-9.19],[3.2,-9.19],[3.8,-8.79],[3.8,-7.89],[3.25,-7.29],[.35,-7.29]]);rimShape.holes.push(m,five);const rim=solid(host.body,rimShape,.12,[0,0,-6.5],white,'U090 actual uncolored rear M5 recessed geometry'),sides=[-1,1].map(sign=>solid(host.body,side(sign),10.8,[0,0,-5.5],white,'U090 own full curved side wall '+sign)),end=box(host.body,[10,1,6.8],[0,-11.5,-2.1],white,'U090 actual lower rear wall below red Grove'),bores=[-8,8].map(x=>ring(host.body,3.3,2.5,10.8,[x,0,-5.5],white,'U090 actual continuous mounting bore wall')),
 frontBoss=ring(host.body,2.9,.85,6,[0,0,-.7],white,'U090 actual front screw-receiving boss through PCB clearance'),rearBoss=ring(host.body,3,1.65,4.8,[0,0,-5.5],white,'U090 actual central rear retaining pedestal'),frontFilm=cylinder(host.body,2.5,.04,[0,0,6.48],materials.plastic(0xecebe4,{roughness:.87}),'U090 actual round BPS adhesive film'),backFilm=solid(host.body,roundedRect(16.2,4.3,.12),.04,[0,7.25,-6.42],materials.plastic(0xe5e1d3,{roughness:.87}),'U090 actual rear PortA adhesive film');for(const f of[frontFilm,backFilm])f.userData={role:'physical-label-substrate',appearanceThicknessInferred:true};return{lid,face,labelSeat,back,rim,sides,end,bores,frontBoss,rearBoss,frontFilm,backFilm};}
function pcbOutline(){const s=new THREE.Shape(),r=3.6,x=2.2,q=Math.acos(x/r),dy=Math.sqrt(r*r-x*x);s.moveTo(-7.7,-10.2);s.lineTo(7.7,-10.2);s.lineTo(10.2,-7.7);s.lineTo(10.2,-dy);s.absarc(8,0,r,-q,q,true);s.lineTo(10.2,7.7);s.lineTo(7.7,10.2);s.lineTo(-7.7,10.2);s.lineTo(-10.2,7.7);s.lineTo(-10.2,dy);s.absarc(-8,0,r,Math.PI-q,Math.PI+q,true);s.lineTo(-10.2,-7.7);s.closePath();circleHole(s,0,0,3.3);for(const x of[-3,-1,1,3])circleHole(s,x,-6.4,.38);return s;}
function board(host){const green=materials.plastic(0x22684a,{roughness:.85}),pcb=solid(host.body,pcbOutline(),.8,[0,0,.5],green,'U090 own octagonal populated PCB and actual open-edge hole reliefs'),posts=[];for(const x of[-6,6])for(const y of[-7,7])posts.push(box(host.body,[1.1,1.1,6],[x,y,-2.5],materials.plastic(0xd6d5c7),'U090 actual PCB post from rear pan'));
 const packages={},legs=[],pads=[];for(const[id,size,pos,count]of[['ht7533',[3.5,2.1,1.1],[-5.4,7.5,1.85],3],['bss138-1',[2.6,1.5,.9],[4.1,6.9,1.75],3],['bss138-2',[2.6,1.5,.9],[7.4,6.9,1.75],3]]){packages[id]=box(host.body,size,pos,black(),'U090 documented '+id+' fixed physical package;layout inferred');for(let i=0;i<count;i++){const x=pos[0]+(i-1)*.85,y=pos[1]+(i===1?-1:1)*(size[1]/2+.3);legs.push(box(host.body,[.35,.9,.22],[x,y,1.41],tin(),'U090 actual package solder leg'));pads.push(box(host.body,[.55,1.05,.025],[x,y,1.3125],tin(),'U090 actual package PCB solderland'));}}
 const passives=[],terminations=[];for(const[x,y,kind]of[[-3.4,9.1,'c'],[-3.4,6,'c'],[-6.1,9.5,'c'],[4.1,9.2,'r'],[7.4,9.2,'r'],[7.2,-5.8,'r'],[7.2,-7.9,'r']]){passives.push(box(host.body,[1.55,.75,.5],[x,y,1.55],kind==='r'?black():materials.plastic(0x9a977f),'U090 own inferred actual passive envelope'));for(const sx of[-1,1])terminations.push(box(host.body,[.3,.8,.51],[x+sx*.65,y,1.555],tin(),'U090 passive retained metal termination'));}return{pcb,posts,packages,legs,pads,passives,terminations};}
function sensor(host){const base=box(host.body,[2.5,2,.2],[0,8.2,1.48],black(),'U090 actual fixed BMP280 lower package on retained LGA contacts'),metal=materials.metal(0xb5b5aa,{roughness:.44}),walls=[];for(const x of[-1.175,1.175])walls.push(box(host.body,[.15,2,.65],[x,8.2,1.905],metal,'U090 BMP280 actual metal pressure-can side wall'));for(const y of[7.275,9.125])walls.push(box(host.body,[2.2,.15,.65],[0,y,1.905],metal,'U090 BMP280 actual metal pressure-can end wall'));const shape=roundedRect(2.5,2,.1);circleHole(shape,.6,.35,.16);const cap=solid(host.body,shape,.15,[0,8.2,2.23],metal,'U090 BMP280 actual closed metal cap and true pressure port'),contacts=[];for(const sx of[-1,1])for(let i=0;i<4;i++)contacts.push(box(host.body,[.5,.28,.08],[sx*1,8.2+(i-1.5)*.45,1.34],tin(),'U090 physical BMP280 eight retained LGA contact pads'));return{base,walls,cap,contacts,pressurePort:{position:[.6,8.55,2.305],radiusMm:.16,scope:'Fixed physical pressure-can port only;no pressure/temperature/altitude/diaphragm model'}};}
function grove(host){const frame=new THREE.Group();frame.name='U090 original actual red four-contact Grove';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const red=materials.plastic(0xbf2531,{roughness:.68}),parts=[],b=(s,p,n,m=red)=>{const o=box(frame,s,p,m,'U090 Grove '+n);parts.push(o);return o;},floor=b([9.8,.65,6.2],[0,-2.275,-3.1],'actual PCB-side molded floor'),back=b([9.8,4.55,.5],[0,-.325,-5.95],'actual deep receiving stop'),walls=[-1,1].map(s=>b([.7,5.2,6.2],[s*4.55,0,-3.1],'actual receiving side wall')),bridge=b([4.8,.45,2.8],[0,1.7,-3.6],'actual partial retention bridge'),guides=[-1,1].map(s=>b([.7,.5,2.8],[s*3.9,-1.7,-1.4],'actual mating guide')),contacts=[],returns=[],tails=[],barrels=[],pads=[];
 for(const x of[-3,-1,1,3]){contacts.push(b([.32,.32,4.8],[x,-.2,-3.1],'actual independent contact',tin()));returns.push(b([.32,2.4,.32],[x,-1.4,-5.6],'actual right-angle return',tin()));tails.push(box(host.body,[.32,.32,.8],[x,-6.4,.9],tin(),'U090 actual retained through-PCB contact tail'));barrels.push(ring(host.body,.36,.26,.8,[x,-6.4,.5],tin(),'U090 Grove actual plated receiving barrel'));for(const z of[.475,1.3])pads.push(ring(host.body,.65,.26,.025,[x,-6.4,z],tin(),'U090 actual Grove annular PCB solderland'));}
 const port=host.add(new Port({id:'grove',label:'Original U090 HY2.0-4P physical receiving socket',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pinGrid:{cols:4,rows:1,pitch:2,center:[0,-.2],order:i=>4-i},pins:spec.grove.pins.map((name,i)=>({n:i+1,name})),meta:{role:'visual-connector',face:'bottom',scope:'Actual four contacts and mechanical cable only;no pressure/temperature/altitude/sampling/I2C/address/electrical/firmware'}}));return{frame,parts,floor,back,walls,bridge,guides,contacts,returns,tails,barrels,pads,port};}
function fixing(host){const s=new THREE.Shape();s.absarc(0,0,1.5,0,Math.PI*2,false);s.holes.push(polygon([[-.22,-1],[.22,-1],[.22,-.22],[1,-.22],[1,.22],[.22,.22],[.22,1],[-.22,1],[-.22,.22],[-1,.22],[-1,-.22],[-.22,-.22]]));const head=solid(host.body,s,.5,[0,0,-6.2],tin(),'U090 actual fixed rear cross-recess fixing head'),floor=cylinder(host.body,1.1,.12,[0,0,-5.7],black(),'U090 actual blind fixing recess floor'),shank=cylinder(host.body,.7,7.45,[0,0,-2.025],tin(),'U090 fixed central shank retained into actual front boss');return{head,floor,shank};}
export function buildBPS(host){const caseParts=shell(host),boardParts=board(host),bmp=sensor(host),input=grove(host),screw=fixing(host);host.bpsAssembly={frame:caseParts.lid.parent,shell:caseParts,board:boardParts,sensor:bmp,input,screw};host.unitStickers=addStickers(host);}
